import React from 'react';
import { Sparkles, AlertTriangle, Wrench, CheckCircle2, RotateCcw, Clock } from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const ActivityFeed = () => {
  const navigate = useNavigate();

  const timelineEvents = [
    { time: '12:30 PM', text: 'Machine LOOM-201 restarted after lube flush', type: 'restart', icon: RotateCcw, color: '#22C55E' },
    { time: '12:25 PM', text: 'Engineer Rajesh Kumar acknowledged work order', type: 'ack', icon: CheckCircle2, color: '#2563EB' },
    { time: '12:18 PM', text: 'Maintenance assigned to LOOM-201 drive shaft', type: 'maint', icon: Wrench, color: '#F97316' },
    { time: '12:14 PM', text: 'Critical alert generated: Vibration 0.42 mm/s', type: 'alert', icon: AlertTriangle, color: '#EF4444' },
    { time: '12:10 PM', text: 'AI model predicted bearing fatigue on LOOM-201', type: 'ai', icon: Sparkles, color: '#8B5CF6' },
  ];

  return (
    <div style={{ display: 'flex', flexDirection: 'column', height: '100%', justifyContent: 'space-between' }}>
      <div>
        <div style={{ fontSize: '0.95rem', fontWeight: '800', color: '#0F172A', marginBottom: '0.85rem', display: 'flex', alignItems: 'center', gap: '0.4rem' }}>
          <Clock size={16} style={{ color: '#2563EB' }} /> Activity Timeline (Real-Time Log)
        </div>

        <div style={{ display: 'flex', flexDirection: 'column', gap: '0.55rem' }}>
          {timelineEvents.map((item, index) => {
            const Icon = item.icon;
            return (
              <div
                key={index}
                style={{
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.75rem',
                  padding: '0.6rem 0.85rem',
                  borderRadius: '8px',
                  background: '#F8FAFC',
                  border: '1px solid #E2E8F0',
                }}
              >
                <div
                  style={{
                    width: '28px',
                    height: '28px',
                    borderRadius: '6px',
                    background: '#ffffff',
                    border: `1px solid ${item.color}40`,
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    color: item.color,
                    flexShrink: 0,
                  }}
                >
                  <Icon size={14} />
                </div>
                <div style={{ flex: 1, display: 'flex', justifyContent: 'space-between', alignItems: 'center', fontSize: '0.8rem' }}>
                  <span style={{ fontWeight: '700', color: '#0F172A' }}>{item.text}</span>
                  <span style={{ fontFamily: 'JetBrains Mono', color: '#64748B', fontWeight: '700', fontSize: '0.74rem' }}>{item.time}</span>
                </div>
              </div>
            );
          })}
        </div>
      </div>

      <button
        className="btn btn-secondary btn-sm"
        onClick={() => navigate('/alerts')}
        style={{ marginTop: '0.85rem', justifyContent: 'center', fontWeight: '700' }}
      >
        View Full System Logs
      </button>
    </div>
  );
};

export default ActivityFeed;
